mapper.select:
SELECT a.message_id, b.title, CASE WHEN LENGTH(b.content) > 160 THEN CONCAT(LEFT(b.content, 160), '…') ELSE b.content END AS summary, b.level, b.sender_name, a.read_status, a.read_time, TO_CHAR(a.received_time, 'YYYY-MM-DD HH24:MI:SS.US') AS received_time, b.expire_time FROM t_sys_inbox_recipient a INNER JOIN t_sys_inbox_message b ON b.id = a.message_id WHERE a.user_id = #{userId} AND a.received_time >= #{beginTime} AND b.status = 'PUBLISHED' AND b.expire_time > CURRENT_TIMESTAMP AND a.read_status = FALSE
AND (a.received_time, a.message_id) < (CAST(#{form.cursorTime} AS timestamp), #{form.cursorMessageId})
ORDER BY a.received_time DESC, a.message_id DESC LIMIT #{limit}

mapper.update:
UPDATE t_sys_inbox_recipient
SET read_status = TRUE, read_time = #{readTime}
WHERE user_id = #{userId} AND received_time >= #{beginTime} AND read_status = FALSE
